#ifndef HEAP_TIMER_H
#define HEAP_TIMER_H

#include <algorithm>
#include <cassert>
#include <chrono>
#include <compare>
#include <deque>
#include <functional>
#include <optional>
#include <stdexcept>
#include <unordered_map>
#include "log.h"
#include "util.h"

namespace ws {

class HeapTimer<Key> {
public:
    using Clock = std::chrono::steady_clock;
    using TimeOutCallback = std::function<void(const Key&)>;

private:
    struct Node {
        Key key;
        Clock::time_point expiration;
        TimeOutCallback callback;

        bool Expired() const noexcept {
            return Clock::now() >= expiration;
        }

        void Swap(Node& other) noexcept {
            std::swap(key, other.key);
            std::swap(expiration, other.expiration);
            std::swap(callback, other.callback);
        }
    };

    log::Logger::Ptr logger_; 
    std::unordered_map<Key, std::size_t> key_to_idx_; 
    std::deque<Node> nodes_; 

    void Swap(std::size_t idx1, std::size_t idx2) noexcept {
        Node temp = nodes_[idx1];
        nodes_[idx1] = nodes_[idx2];
        nodes_[idx2] = temp;

        key_to_idx_[nodes_[idx1].key] = idx1;
        key_to_idx_[nodes_[idx2].key] = idx2;
    }

    void Adjust(const Key& key, Clock::time_point expiration, std::optional<TimeOutCallback> callback) {
        auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) {
            throw std::out_of_range("Key not found");
        }
        std::size_t idx = it->second;
        nodes_[idx].expiration = expiration;
        if(callback.has_value()){
          nodes_[idx].callback = callback.value();
        }
    }

    Key RemoveByIndex(std::size_t idx) noexcept {
        Key key = nodes_[idx].key;
        if (nodes_.size() == 1) {
            nodes_.clear();
            key_to_idx_.erase(key);
        } else {
            Swap(idx, nodes_.size() - 1);
            nodes_.pop_back();
            key_to_idx_.erase(key);
        }
        return key;
    }

    void ShiftUp(std::size_t idx) noexcept {
        while (idx > 0) {
            auto parent_idx = Parent(idx);
            if (!parent_idx.has_value()) break;
            std::size_t p = parent_idx.value();
            if (nodes_[idx] <= nodes_[p]) break;
            Swap(idx, p);
            idx = p;
        }
    }

    void ShiftDown(std::size_t idx) noexcept {
        while (true) {
            auto child_idx = SmallChild(idx);
            if (!child_idx.has_value()) break;
            std::size_t c = child_idx.value();
            if (nodes_[idx] <= nodes_[c]) break;
            Swap(idx, c);
            idx = c;
        }
    }

    bool ValidIndex(std::size_t idx) const noexcept {
        return idx < nodes_.size();
    }

    std::optional<std::size_t> Parent(std::size_t idx) const noexcept {
        if (idx == 0) return std::nullopt;
        return (idx - 1) / 2;
    }

    std::optional<std::size_t> SmallChild(std::size_t idx) const noexcept {
        std::size_t left = 2 * idx + 1;
        std::size_t right = 2 * idx + 2;

        if (!ValidIndex(left)) return std::nullopt;
        if (!ValidIndex(right)) return left;

        return (nodes_[left] <= nodes_[right]) ? left : right;
    }

public:
    HeapTimer(log::Logger::Ptr logger = log::RootLogger()) noexcept : logger_(logger) {}

    HeapTimer(HeapTimer&&) = delete;
    HeapTimer& operator=(HeapTimer&&) = delete;
    HeapTimer(const HeapTimer&) = delete;
    HeapTimer& operator=(const HeapTimer&) = delete;

    void Adjust(const Key& key, Clock::duration expiration) {
        Adjust(key, Clock::now() + expiration);
    }

    void Adjust(const Key& key, Clock::time_point expiration) {
        Adjust(key, expiration, std::nullopt);
    }

    void Push(const Key& key, Clock::duration expiration, TimeOutCallback callback) noexcept {
        auto it = key_to_idx_.find(key);
        if (it != key_to_idx_.end()) {
            Adjust(key, Clock::now() + expiration, callback);
        } else {
            nodes_.emplace_back(key, Clock::now() + expiration, callback);
            key_to_idx_[key] = nodes_.size() - 1;
            ShiftUp(nodes_.size() - 1);
        }
    }

    void Push(const Key& key, Clock::time_point expiration, TimeOutCallback callback) noexcept {
        auto it = key_to_idx_.find(key);
        if (it != key_to_idx_.end()) {
            Adjust(key, expiration, callback);
        } else {
            nodes_.emplace_back(key, expiration, callback);
            key_to_idx_[key] = nodes_.size() - 1;
            ShiftUp(nodes_.size() - 1);
        }
    }

    void Tick() noexcept {
        while (!nodes_.empty() && nodes_[0].Expired()) {
            Key key = RemoveByIndex(0);
            try {
                nodes_[0].callback(key);
            } catch (const std::exception& e) {
                logger_->Error("Callback threw exception: {}", e.what());
            }
        }
    }

    bool Remove(const Key& key) noexcept {
        auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) return false;
        std::size_t idx = it->second;
        RemoveByIndex(idx);
        return true;
    }

    void Invoke(const Key& key) {
        auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) {
            throw std::out_of_range("Key not found");
        }
        std::size_t idx = it->second;
        RemoveByIndex(idx);
        try {
            nodes_[0].callback(key);
        } catch (const std::exception& e) {
            logger_->Error("Callback threw exception: {}", e.what());
        }
    }

    Key Pop() noexcept {
        assert(!nodes_.empty());
        return RemoveByIndex(0);
    }

    void Clear() noexcept {
        nodes_.clear();
        key_to_idx_.clear();
    }

    bool Contain(const Key& key) const noexcept {
        return key_to_idx_.find(key) != key_to_idx_.end();
    }

    bool Empty() const noexcept {
        assert(nodes_.empty() == key_to_idx_.empty());
        return nodes_.empty();
    }

    std::size_t Size() const noexcept {
        assert(nodes_.size() == key_to_idx_.size());
        return nodes_.size();
    }

    Clock::duration ToNextTick() noexcept {
        Tick();
        if (nodes_.empty()) return Clock::duration::zero();
        return nodes_[0].expiration - Clock::now();
    }
};

}

#endif // HEAP_TIMER_H
